# line-art equipment SVGs (pathLength=1 so stroke-draw works)
def _g(inner,vb,cls='eq',sw=3): return '<svg class="%s" viewBox="%s" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="%s" stroke-linecap="round" stroke-linejoin="round">%s</g></svg>'%(cls,vb,sw,inner)
def dumbbell(cls='eq',sw=3): return _g('<path pathLength="1" d="M70 45H190"/><rect pathLength="1" x="50" y="25" width="20" height="40" rx="4"/><rect pathLength="1" x="30" y="12" width="20" height="66" rx="5"/><rect pathLength="1" x="190" y="25" width="20" height="40" rx="4"/><rect pathLength="1" x="210" y="12" width="20" height="66" rx="5"/><path pathLength="1" d="M14 45H30M230 45H246"/>','0 0 260 90',cls,sw)
def kettle(cls='eq',sw=3): return _g('<path pathLength="1" d="M38 40C38 6 82 6 82 40"/><path pathLength="1" d="M28 40H92"/><path pathLength="1" d="M28 40C6 60 8 118 60 118C112 118 114 60 92 40"/><path pathLength="1" d="M40 100H80"/>','0 0 120 130',cls,sw)
def glove(cls='eq',sw=3): return _g('<path pathLength="1" d="M34 70C14 40 26 10 62 10C100 10 112 36 106 64C103 80 94 86 84 90V122H38V92C36 84 35 78 34 70Z"/><path pathLength="1" d="M38 108H84"/><path pathLength="1" d="M34 70C30 58 40 52 52 58C62 64 66 74 58 82"/>','0 0 120 132',cls,sw)
def plate(cls='eq',sw=3): return _g('<circle pathLength="1" cx="60" cy="60" r="54"/><circle pathLength="1" cx="60" cy="60" r="38"/><circle pathLength="1" cx="60" cy="60" r="10"/><path pathLength="1" d="M60 22V6M60 114V98M22 60H6M114 60H98"/>','0 0 120 120',cls,sw)
def bag(cls='eq',sw=3): return _g('<path pathLength="1" d="M60 0V34"/><path pathLength="1" d="M30 34H90"/><rect pathLength="1" x="24" y="34" width="72" height="190" rx="22"/><path pathLength="1" d="M24 80H96M24 150H96"/>','0 0 120 230',cls,sw)
